    mongodb.connect('mongodb://localhost:27017', function(err, client) {
      if (err) return callback(err);

      const db = client.db('users');
      db.collection('profiles').findOne({userId}, function(err, profile) {
        if (err) {
          client.close();
          return callback(err);
        }

        fs.readFile(`./userdata/${userId}.json`, 'utf8', function(err, fileData) {
          client.close();
          if (err) return callback(err);

          // More nested processing here...
          callback(null, {profile, fileData});
        });
      });
    });
  }
};

