package pool

import (
	"sync"
)

type Job struct {
	ID   int
	Data string
}

type Dispatcher struct {
	sem        chan struct{}
	jobQueue   chan Job
	results    chan string
	wg         sync.WaitGroup
	shutdownCh chan struct{}
}

func NewDispatcher(maxWorkers int) *Dispatcher {
	return &Dispatcher{
		sem:        make(chan struct{}, maxWorkers),
		jobQueue:   make(chan Job),
		results:    make(chan string),
		shutdownCh: make(chan struct{}),
	}
}

func (d *Dispatcher) Submit(job Job) {
	d.jobQueue <- job
}

func (d *Dispatcher) Start() {
	d.wg.Add(1)
	go func() {
		defer d.wg.Done()
		for {
			select {
			case job := <-d.jobQueue:
				d.sem <- struct{}{}
				go func(j Job) {
					defer func() { <-d.sem }()
					// Simulate processing
					d.results <- j.Data
				}(job)
			case <-d.shutdownCh:
				return
			}
		}
	}()
}

func (d *Dispatcher) Stop() {
	close(d.shutdownCh)
	d.wg.Wait()
	close(d.results)
}
